// Helper functions to count open and close brackets
function countOpen(brackets: string, index: int) : int
    requires 0 <= index <= brackets.Length
    ensures 0 <= countOpen(brackets, index) <= index
{
    var count := 0;
    var i := 0;
    while i < index
        invariant 0 <= i <= index
        invariant count == countOpen(brackets, i)
    {
        if brackets[i] == '(' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function countClose(brackets: string, index: int) : int
    requires 0 <= index <= brackets.Length
    ensures 0 <= countClose(brackets, index) <= index
{
    var count := 0;
    var i := 0;
    while i < index
        invariant 0 <= i <= index
        invariant count == countClose(brackets, i)
    {
        if brackets[i] == ')' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}
